  rn_HI rn <= x \/ (rn_t rn + 80 <= x < rn_t rn + 2888) \/ (rn_spb rn + 24 * 2 ^ 32 <= x < rn_spb rn + 25 * 2 ^ 32) \/ (rn_ris rn <= x < rn_ris rn + 4096)
